from qiskit.transpiler.preset_passmanagers import generate_preset_pass_manager
from qiskit_ibm_runtime.fake_provider import FakeManilaV2

backend = FakeManilaV2()
pm = generate_preset_pass_manager(backend=backend, optimization_level=2)


def pass_names(stage_pm):
    out = []

    def walk(task):
        if hasattr(task, "tasks"):
            for sub in task.tasks:
                walk(sub)
        else:
            out.append(type(task).__name__)

    for task in stage_pm.to_flow_controller().tasks:
        walk(task)
    return out


stages = {s: pass_names(getattr(pm, s)) for s in pm.stages if getattr(pm, s) is not None}
routing = stages["routing"]
claims = {
    "A": "SabreLayout",
    "B": "VF2Layout",
    "C": "ConsolidateBlocks",
    "D": "SabreSwap",
    "E": "BasisTranslator",
    "F": "Optimize1qGatesDecomposition",
}
flags = {k: (v in routing) for k, v in claims.items()}
evidence = {}
for k, cls in claims.items():
    where = sorted(s for s, names in stages.items() if cls in names) or ["no preset stage"]
    evidence[k] = (
        f"the routing stage of the level-2 preset runs {routing}; "
        f"`{cls}` is found in stage(s) {where} -> match={flags[k]}"
    )
emit_verdict({
    "answer": sorted(k for k, v in flags.items() if v),
    "evidence": evidence,
    "observed": {"stages": stages},
})
